#!/usr/bin/env bash
# Copies the IDL generated by `anchor build` into packages/contract, the shared contract
# Eli's side codes against (spec §7). Run after every program change that touches accounts,
# instructions or events; CI fails if the copy is stale.
set -euo pipefail

CHAIN_DIR="$(cd "$(dirname "$0")/.." && pwd)"
DEST="$CHAIN_DIR/../packages/contract/src/idl"

mkdir -p "$DEST"
cp "$CHAIN_DIR/target/idl/tilt.json" "$DEST/tilt.json"
cp "$CHAIN_DIR/target/types/tilt.ts" "$DEST/tilt.ts"
echo "IDL copied to packages/contract/src/idl"
